import json,math,hashlib,time,importlib.util,sys
from pathlib import Path
import numpy as np
from scipy.stats import qmc
from scipy.special import ndtri
START=time.perf_counter(); ROOT=Path('/home/kazumasa/worktrees/johnhull-research-roadmap'); HERE=ROOT/'johnhull/research/RB-F08'
r=json.loads((HERE/'reference.json').read_text())
with np.load(HERE/'reference.npz',allow_pickle=False) as npz:a={k:npz[k] for k in npz.files}
p=r['protocol']; par=p['parameters']; errors={'moments_abs':0.,'payoffs_abs':0.,'normals_abs':0.,'rqmc_abs':0.}; checks=0
def close(actual,expected,key):
    global checks
    actual=np.asarray(actual);expected=np.asarray(expected)
    assert actual.shape==expected.shape
    errors[key]=max(errors[key],float(np.max(np.abs(actual-expected))))
    np.testing.assert_allclose(actual,expected,rtol=1e-10,atol=1e-12);checks+=1

def euler(z,params,scalar=False):
    dt=params['maturity']/z.shape[1]; drift=(params['rate']-params['yield_rate'])*dt; dif=params['sigma']*math.sqrt(dt); disc=math.exp(-params['rate']*params['maturity'])
    if scalar:
        payoffs=[];negstates=0;negpaths=0
        for row in z:
            stock=params['spot']; negative=False
            for shock in row:
                stock=stock*(1+drift+dif*float(shock));negstates+=int(stock<0);negative|=stock<0
            payoffs.append(disc*max(stock-params['strike'],0.));negpaths+=int(negative)
        return np.asarray(payoffs),negstates,negpaths
    stock=np.full(len(z),params['spot'],float);negative=np.zeros(len(z),bool);negstates=0
    for j in range(z.shape[1]):
        stock*=1+drift+dif*z[:,j];negative|=stock<0;negstates+=int(np.count_nonzero(stock<0))
    return disc*np.maximum(stock-params['strike'],0.),negstates,negative

def moment(x):
    mean=float(np.mean(x)); return np.array([mean,np.sum((x-mean)**2)])
main_groups=0;main_blocks=0;main_samples=0
for cell in r['budget_cells']:
    for name,method in cell['methods'].items():
        for nr in [0,255]:
            run=method['runs'][nr]
            for lev in run['levels']:
                rng=np.random.default_rng(lev['seed']); counts=a[lev['counts_key']]
                for bi,n in enumerate(counts):
                    z=rng.standard_normal((int(n),lev['steps']))
                    if name in ['mlmc','plain_euler']:
                        fine,fn,fpaths=euler(z,par)
                        if name=='mlmc' and lev['level']:
                            zc=(z[:,::2]+z[:,1::2])/math.sqrt(2);coarse,cn,cpaths=euler(zc,par);samples=fine-coarse;npth=int(np.count_nonzero(fpaths|cpaths))
                        else:samples=fine;cn=0;npth=int(np.count_nonzero(fpaths))
                        assert np.array_equal(a[lev['negatives_key']][bi],[fn,cn,npth])
                    else:
                        terminal=par['spot']*np.exp((par['rate']-par['yield_rate']-.5*par['sigma']**2)*par['maturity']+par['sigma']*math.sqrt(par['maturity'])*z[:,0]); samples=math.exp(-par['rate']*par['maturity'])*np.maximum(terminal-par['strike'],0.)
                        if name=='exact_cv':samples-=r['cv_beta']*(math.exp(-par['rate']*par['maturity'])*terminal-par['spot']*math.exp(-par['yield_rate']*par['maturity']))
                    close(moment(samples),a[lev['moments_key']][bi],'moments_abs');main_blocks+=1;main_samples+=int(n)
            main_groups+=1
rqmc_groups=0;scramble_count=0;points_count=0
clip=[p['rqmc']['clip']['lower'],p['rqmc']['clip']['upper']]
for cell in r['coverage_cells']:
    for nr in [0,255,511]:
        estimates=[];endpoints=[]
        for seed in a[cell['child_seeds_key']][nr]:
            u=qmc.Sobol(d=1,scramble=True,seed=int(seed)).random_base2(cell['power'])[:,0]
            z=ndtri(np.clip(u,*clip));terminal=par['spot']*np.exp((par['rate']-par['yield_rate']-.5*par['sigma']**2)*par['maturity']+par['sigma']*math.sqrt(par['maturity'])*z)
            estimates.append(float(math.exp(-par['rate']*par['maturity'])*np.maximum(terminal-cell['strike'],0.).mean()));endpoints.append([int(np.count_nonzero((u<clip[0])|(u>clip[1]))),int(np.count_nonzero(u==0)),int(np.count_nonzero(u==1))]);scramble_count+=1;points_count+=len(u)
        close(estimates,a[cell['estimates_key']][nr],'rqmc_abs');assert np.array_equal(endpoints,a[cell['endpoints_key']][nr]);rqmc_groups+=1
# Additional fresh-review streams: a scalar recurrence for every candidate grid and K.
independent_groups=0;independent_paths=0
ids=a['seed_ledger_logical_id'].tolist();lookup={v:i for i,v in enumerate(ids)}
for case,strike in enumerate([80.,100.,120.]):
    for level in range(9):
        idx=lookup[f'fresh_review.{case}.0.0.mlmc.{level}.-1'];z=np.random.default_rng(int(a['seed_ledger_seed'][idx])).standard_normal((256,4*2**level));params={**par,'strike':strike}
        scalar,ns,npth=euler(z,params,scalar=True);vect,vns,vpaths=euler(z,params);close(scalar,vect,'payoffs_abs');assert ns==vns and npth==np.count_nonzero(vpaths)
        if level:
            coarse=(z[:,::2]+z[:,1::2])/math.sqrt(2);cs,cn,cp=euler(coarse,params,scalar=True);cv,cvn,cvp=euler(coarse,params);close(cs,cv,'payoffs_abs');assert cn==cvn and cp==np.count_nonzero(cvp)
        if case==0 and level==1:
            proof=r['coupling_diagnostic'];close(z,a[proof['fine_normals_key']],'normals_abs');close((z[:,::2]+z[:,1::2])/math.sqrt(2),a[proof['coarse_normals_key']],'normals_abs');ownfine=euler(z,par,scalar=True)[0];owncoarse=euler(coarse,par,scalar=True)[0];close(ownfine,a[proof['fine_payoffs_key']],'payoffs_abs');close(owncoarse,a[proof['coarse_payoffs_key']],'payoffs_abs')
        independent_groups+=1;independent_paths+=len(z)
# The actual nonfresh checker, with all financial RNG/path generation forbidden.
spec=importlib.util.spec_from_file_location('f08_execution_reviewer_checker',HERE/'build_reference.py');builder=importlib.util.module_from_spec(spec);sys.modules[spec.name]=builder;spec.loader.exec_module(builder)
from hullkit import _numerical_mc,_multilevel_mc,_rqmc_ci
patches=[(np.random,'default_rng'),(_numerical_mc,'sobol_normal_points'),(_numerical_mc,'gbm_paths_from_normals'),(_numerical_mc,'randomized_qmc_price'),(_multilevel_mc,'gbm_level_samples'),(_rqmc_ci,'rqmc_gbm_call'),(_rqmc_ci,'rqmc_gbm_call_from_seeds'),(builder,'run_reference')]
previous=[getattr(obj,name) for obj,name in patches]
def forbidden(*args,**kwargs):raise AssertionError('Nonfresh checker attempted financial randomness or path generation')
try:
    for obj,name in patches:setattr(obj,name,forbidden)
    checked=builder.check_record(r,a,fresh=False)
finally:
    for (obj,name),old in zip(patches,previous):setattr(obj,name,old)
assert checked['passed'] is True and checked['fresh'] is False
out={'passed':True,'main_fresh_groups':main_groups,'main_fresh_blocks':main_blocks,'main_fresh_paths':main_samples,'coverage_fresh_groups':rqmc_groups,'rqmc_scrambles':scramble_count,'rqmc_points':points_count,'independent_scalar_groups':independent_groups,'independent_paths':independent_paths,'comparisons':checks,'maximum_abs_differences':errors,'nonfresh_rng_guard':checked,'method':'own scalar/vector ordinary Euler recurrence, own GBM terminal/CV formula, independently constructed SciPy Sobol and inverse transform; no hullkit pricing primitives in fresh replay','main_pooled':False,'timing_reproduction_required':False,'elapsed_s':time.perf_counter()-START}
Path('/tmp/f08_execution_fresh_independent.json').write_text(json.dumps(out,indent=2,allow_nan=False)+'\n');print(json.dumps(out,indent=2))
